const body = $json.body || $json;
const allowedActions = new Set(['OUTREACH_RECHECK', 'IMPORT_DISCOVER', 'EXPORT_PROCESS', 'CRM_SYNC']);
const allowedImports = new Set(['PROSPECT_LEADS', 'PRODUCT_MASTER_UPDATE', 'CUSTOMER_DEALS', 'CUSTOMER_DEAL_LINES']);
const action = String(body.action || '').trim().toUpperCase();
const resourceId = String(body.resource_id || '').trim();
const requestId = String(body.request_id || '').trim();
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const hashPattern = /^[0-9a-f]{64}$/i;
if (!allowedActions.has(action)) throw new Error('Invalid Phase 7 action');
if (requestId && !uuidPattern.test(requestId)) throw new Error('Invalid request_id');
if (action === 'IMPORT_DISCOVER') {
  const importType = String(body.import_type || '').trim().toUpperCase();
  const manifest = body.manifest || {};
  if (!allowedImports.has(importType)) throw new Error('Invalid import_type');
  if (!requestId) throw new Error('request_id is required for shared import discovery');
  if (![manifest.sourceSha256Before, manifest.localSha256, manifest.sourceSha256After].every(value => hashPattern.test(String(value || '')))) throw new Error('Invalid shared import hashes');
  if (new Set([manifest.sourceSha256Before, manifest.localSha256, manifest.sourceSha256After].map(value => String(value).toLowerCase())).size !== 1) throw new Error('Shared source changed during staging');
  const mutations = manifest.sourceMutations || {};
  if (['modified','deleted','renamed','moved','created'].some(key => Number(mutations[key] || 0) !== 0) || manifest.autoCommit === true) throw new Error('Shared import read-only contract violated');
  return [{ json: { action, import_type: importType, manifest, request_id: requestId } }];
}
if (!uuidPattern.test(resourceId)) throw new Error('Invalid resource_id');
return [{ json: { action, resource_id: resourceId, request_id: requestId || resourceId } }];

const result = $json.result || $json;
const request = $('02 Validate Orchestration Request').item.json;
return [{ json: { request_id: request.request_id, action: request.action, resource_id: request.resource_id || null, manifest_digest: result.manifest_digest || null, status: String(result.status || 'QUEUED'), queued_items: Number(result.queued_items || 0), provider_calls: Number(result.provider_calls || 0) } }];
